info:
三菱 MC 协议驱动 (3E/4E帧 + 位元件拆包 + 模拟模式)

输入: msg.payload = { id, deviceName, plcIp, plcPort, protocolParams, tags[], timeout, maxRetries, retryInterval }
输出: msg.payload = { deviceId, deviceName, success, data, error, driverType, plcIp, plcPort }

v10 Phase 1a — 独立可测，不依赖后端

func:
// === sf-mc-driver v10: 3E/4E帧 + 位元件拆包 + 智能批量 + 模拟模式 ===
var net = global.get('net');
var SIM_MODE = global.get('edge_simulationMode') || false;
var DEBUG = global.get('edge_debug') || false;

var dev = msg.payload;
if (!dev || !dev.id) {
    node.warn('[MC-Driver] Invalid input, missing device id');
    return null;
}

// === Singleton lock (60s expiry) ===
var lock = global.get('edge_mc_driver_lock');
if (lock && (Date.now() - lock.ts < 60000)) {
    if (DEBUG) node.warn('[MC-Driver] Lock held (' + (Date.now()-lock.ts) + 'ms old), dropping duplicate');
    return null;  // 🔧 BUG-1: Reject ALL re-entry including same instance
}
global.set('edge_mc_driver_lock', { ts: Date.now(), instanceId: node.id });

var pp = dev.protocolParams || {};
var mcFrame = pp.mcFrame || '3E';
// 🔧 P1-3: Sanitize serialNo
if (pp.serialNo != null) {
    pp.serialNo = parseInt(pp.serialNo, 10) || 0;
    if (pp.serialNo < 0 || pp.serialNo > 65535) pp.serialNo = pp.serialNo & 0xFFFF;
}
var roundStart = Date.now();

// === MC Device Code Map ===
var MC_DEVICE_CODES = {
    'D': 0xA8, 'W': 0xB4, 'X': 0x9C, 'Y': 0x9D,
    'M': 0x90, 'L': 0x92, 'B': 0xA0, 'R': 0xAF
};
var BIT_DEVICES = { 'X': true, 'Y': true, 'M': true, 'L': true, 'B': true };

// === Simulation Mode ===
if (SIM_MODE || !net) {
    setTimeout(function () {
        var simData = {};
        (dev.tags || []).forEach(function (t) {
            simData[t.id] = {
                rawValue: BIT_DEVICES[t.regType] ? (Math.random() > 0.5 ? 1 : 0) : Math.floor(Math.random() * 1000),
                quality: 0,
                ts: new Date().toISOString()
            };
        });
        var ok = true;  // always succeed in sim mode (no random failure)
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: ok,
            data: simData,
            error: ok ? null : 'Simulated timeout',
            driverType: 'driver-mc-protocol',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: Date.now() - roundStart
        };
        node.status({
            fill: ok ? 'green' : 'red',
            shape: 'dot',
            text: dev.deviceName + ' SIM ' + (ok ? 'OK' : 'FAIL')
        });
        node.send(msg);
        global.set('edge_mc_driver_lock', null);
    }, 10 + Math.random() * 30);
    return null;
}

// ===== Real TCP Mode =====

// Step 1: Group tags by register type + address proximity clustering
var byRegType = {};
(dev.tags || []).forEach(function (t) {
    var rt = t.regType || 'D';
    if (!MC_DEVICE_CODES[rt]) { if (DEBUG) node.warn("[MC-Driver] Unknown regType: " + rt + ", defaulting to D"); rt = "D"; }  // 🔧 BUG-12
    var addr = parseInt(t.addr, 10);
    if (isNaN(addr) || addr < 0) { if (DEBUG) node.warn("[MC-Driver] Invalid addr for tag " + t.id); return; }  // 🔧 BUG-12
    t.addr = addr;  // normalize
    if (!byRegType[rt]) byRegType[rt] = [];
    byRegType[rt].push(t);
});

var regGroups = [];
var MAX_GAP = 20;
var MAX_CLUSTER = 50;
Object.keys(byRegType).forEach(function (rt) {
    var tags = byRegType[rt].slice().sort(function (a, b) { return a.addr - b.addr; });  // 🔧 BUG-11: slice first
    var cluster = [tags[0]];
    for (var i = 1; i < tags.length; i++) {
        var gap = tags[i].addr - cluster[cluster.length - 1].addr;
        if (gap <= MAX_GAP && cluster.length < MAX_CLUSTER) {
            cluster.push(tags[i]);
        } else {
            regGroups.push({ regType: rt, tags: cluster });
            cluster = [tags[i]];
        }
    }
    if (cluster.length > 0) regGroups.push({ regType: rt, tags: cluster });
});

if (regGroups.length === 0) {
    msg.payload = {
        deviceId: dev.id, deviceName: dev.deviceName,
        success: false, data: {}, error: 'No valid register groups',
        driverType: 'driver-mc-protocol', plcIp: dev.plcIp, plcPort: dev.plcPort,
        roundTimeMs: Date.now() - roundStart
    };
    global.set('edge_mc_driver_lock', null);
    node.send(msg);
    return null;
}

if (DEBUG) node.warn('[MC-Driver] ' + dev.deviceName + ' groups=' + regGroups.length + ' frame=' + mcFrame);

// Step 2: Build MC Frame (serialNo auto-increments per frame)
var _sentSerialNo = 0;
function buildMCFrame(startAddr, wordCount, stationNo, regType, frameType) {
    var deviceCode = MC_DEVICE_CODES[regType] || 0xA8;
    if (frameType === '4E') {
        var hasSN = (pp.serialNo != null && pp.serialNo !== 0);
        var bufLen = hasSN ? 24 : 22;
        var buf = Buffer.alloc(bufLen);
        buf[0] = 0x54; buf[1] = 0x00;
        buf[2] = pp.networkNo || 0;
        buf[3] = 0xFF;
        buf[4] = 0xFF; buf[5] = 0x03;
        buf[6] = stationNo || 0;
        buf[7] = hasSN ? 0x0F : 0x0D; buf[8] = 0x00;
        buf[9] = 0x10; buf[10] = 0x00;
        var off = 11;
        if (hasSN) { var sn = (pp.serialNo++ & 0xFFFF); buf[off] = sn & 0xFF; buf[off + 1] = (sn >> 8) & 0xFF; off += 2; _sentSerialNo = sn; }  // 🔧 increment per frame + store
        buf[off] = 0x01; buf[off + 1] = 0x04; off += 2;
        buf[off] = 0x00; buf[off + 1] = 0x00; off += 2;
        buf.writeUInt32LE(startAddr, off); off += 4;
        buf[off] = deviceCode; off += 1;
        buf.writeUInt16LE(wordCount, off);
        return buf;
    }
    // 3E frame (21 bytes)
    var buf = Buffer.alloc(21);
    buf[0] = 0x50; buf[1] = 0x00;
    buf[2] = pp.networkNo || 0; buf[3] = 0xFF; buf[4] = 0xFF; buf[5] = 0x03;  // 🔧 BUG-8: use pp.networkNo
    buf[6] = stationNo || 0; buf[7] = 0x0C; buf[8] = 0x00;
    buf[9] = 0x10; buf[10] = 0x00;
    buf[11] = 0x01; buf[12] = 0x04;
    buf[13] = 0x00; buf[14] = 0x00;
    buf[15] = startAddr & 0xFF;
    buf[16] = (startAddr >> 8) & 0xFF;
    buf[17] = (startAddr >> 16) & 0xFF;
    buf[18] = deviceCode;
    buf.writeUInt16LE(wordCount, 19);
    return buf;
}

// Step 3: Parse MC Response

// MC Protocol error code map
var MC_ERROR_CODES = {
    0xC050: "CPU busy, retry later",
    0xC051: "Device/register not supported",
    0xC052: "Address out of range",
    0xC053: "Batch size out of range",
    0xC054: "Write protect error",
    0xC055: "Remote operation error",
    0xC056: "File not found",
    0xC057: "File name error",
    0xC059: "Points/word count out of range",
    0xC05B: "CPU type mismatch",
    0xC05C: "Remote password error",
    0xC05F: "CPU module error",
    0xC061: "Monitor timer timeout",
    0xC06F: "ASCII code error",
    0xC070: "Frame length error",
    0xC0D0: "PLC status error (not running)",
    0x4004: "4E: Device/register not supported",
    0x401A: "4E: Address out of range",
    0x4028: "4E: Points/word count out of range",
};
function _mcErrorText(code) {
    return MC_ERROR_CODES[code] || ("Unknown MC error 0x"+code.toString(16).toUpperCase());
}

function parseMCResponse(buf, startAddr, regType) {
    if (!buf || buf.length < 11) return null;
    var subheader = (buf[0] === 0xD0) ? 0x50 : ((buf[0] === 0xD4) ? 0xD4 : 0);
    if (subheader === 0) return null;
    var endCode = buf.readUInt16LE(9);
    if (endCode !== 0) { return { mcError: endCode, mcErrorText: _mcErrorText(endCode) }; }  // 🔧 BUG-3: immediate failure
    var dataLen = buf.readUInt16LE(7) - ((mcFrame === '4E') ? 4 : 2);  // 4E: subtract endCode+serialNo
    if (dataLen < 0 || dataLen > 2000) return null;  // 🔧 sanity: max 2000 bytes (1000 words)
    var dataStart = (mcFrame === '4E') ? 13 : 11;  // 4E response always has serial no field
    // 🔧 Verify response serialNo matches request (4E only)
    if (mcFrame === '4E' && _frameSerialNo > 0 && buf.length >= 13) {
        var respSN = buf.readUInt16LE(11);
        if (respSN !== _frameSerialNo) return null;  // mismatched packet
    }
    if (buf.length < dataStart + dataLen) return null;
    var result = {};
    if (BIT_DEVICES[regType]) {
        for (var w = 0; w < dataLen / 2; w++) {
            var wordVal = buf.readUInt16LE(dataStart + w * 2);
            for (var b = 0; b < 16; b++) {
                result[regType + (startAddr + w * 16 + b)] = (wordVal >> b) & 1;
            }
        }
    } else {
        for (var i = 0; i < dataLen / 2; i++) {
            result[regType + (startAddr + i)] = buf.readInt16LE(dataStart + i * 2);
        }
    }
    return result;
}

// Step 4: Process groups sequentially
var allStdData = {};
var hasFailed = false;
var firstError = '';
function _clampInt(v, def, min, max) { var n=parseInt(v,10); if(isNaN(n)) n=def; return Math.max(min,Math.min(n,max)); }
var timeout = _clampInt(dev.timeout, 3000, 500, 30000);  // 🔧 NaN-safe
var maxRetries = _clampInt(dev.maxRetries, 2, 0, 10);
var retryInterval = _clampInt(dev.retryInterval, 300, 50, 10000);

function processGroup(gi) {
    if (gi >= regGroups.length) {
        // All groups done
        var roundTimeMs = Date.now() - roundStart;
        if (DEBUG) node.warn('[MC-Driver] ' + dev.deviceName + ' done in ' + roundTimeMs + 'ms, groups=' + regGroups.length + ' failed=' + hasFailed);
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: !hasFailed,
            data: allStdData,
            error: hasFailed ? firstError : null,
            driverType: 'driver-mc-protocol',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: roundTimeMs
        };
        node.status({
            fill: hasFailed ? 'red' : 'green',
            shape: 'dot',
            text: dev.deviceName + ' ' + Object.keys(allStdData).length + ' vals'
        });
        global.set('edge_mc_driver_lock', null);
        node.send(msg);
        return;
    }

    var grp = regGroups[gi];
    var addrs = grp.tags.map(function (t) { return t.addr; });
    var startA = addrs[0];
    var isBit = BIT_DEVICES[grp.regType] || false;
    if (isBit) { startA = startA - (startA % 16); }  // 🔧 BUG-13: align to 16
    var wordCount;
    if (isBit) {
        wordCount = Math.ceil((addrs[addrs.length - 1] - startA + 1) / 16);
    } else {
        wordCount = addrs[addrs.length - 1] - startA + 1;
    }

    // 🔧 P0: Enforce MC protocol word count limit (960 for 3E, adjust per device)
    var MAX_WORDS = isBit ? 15360 : ((mcFrame === "4E") ? 960 : 960);  // 🔧 bit: 960*16 addr span
    if (wordCount > MAX_WORDS) {
        // Split group into subgroups that fit within limit
        var newGroups = [];
        var subStart = 0;
        while (subStart < grp.tags.length) {
            var subEnd = subStart;
            while (subEnd < grp.tags.length && (grp.tags[subEnd].addr - grp.tags[subStart].addr) < MAX_WORDS) {
                subEnd++;
            }
            newGroups.push({ regType: grp.regType, tags: grp.tags.slice(subStart, subEnd) });
            subStart = subEnd;
        }
        // Replace current group position with split subgroups
        regGroups.splice.apply(regGroups, [gi, 1].concat(newGroups));
        // Reprocess this index (now points to first split subgroup)
        setTimeout(function () { processGroup(gi); }, 0);
        return;
    }

    function attemptGroup(attempt) {
        if (attempt > maxRetries) {
            hasFailed = true;
            if (!firstError) firstError = 'MC read failed for ' + grp.regType + startA;
            setTimeout(function () { processGroup(gi + 1); }, 0);
            return;
        }

        var client = new net.Socket();
        var buf = Buffer.alloc(0);
        var resolved = false;

        client.setTimeout(timeout);

        client.connect(dev.plcPort, dev.plcIp, function () {
            try {  // 🔧 BUG-2
            var frame = buildMCFrame(startA, wordCount, pp.stationNo || 0, grp.regType, mcFrame);
            client.write(frame);
            } catch(_e) { node.warn('[MC-Driver] connect error: '+_e.message); if(!resolved){resolved=true;try{client.destroy();}catch(e2){}} setTimeout(function(){attemptGroup(attempt+1);},retryInterval); }
        });

        client.on('data', function (chunk) {
            try {  // 🔧 BUG-2: async exception handler
            buf = Buffer.concat([buf, chunk]);
            var hdrLen = (mcFrame === '4E') ? 13 : 11;  // 4E response always has serial no
            if (!resolved && buf.length >= hdrLen) {
                var dataLen = buf.readUInt16LE(7) - ((mcFrame === '4E') ? 4 : 2);  // 4E: subtract endCode+serialNo
                if (dataLen < 0 || dataLen > 2000) { resolved = true; try { client.destroy(); } catch(e){} setTimeout(function(){attemptGroup(attempt+1);},retryInterval); return; }  // 🔧 bad frame
                if (buf.length >= hdrLen + dataLen) {
                    resolved = true;
                    var raw = parseMCResponse(buf, startA, grp.regType);
                    if (raw && raw.mcError) {
                        // 🔧 BUG-3: PLC business error → fail immediately, no retry
                        hasFailed = true;
                        if (!firstError) firstError = "[PLC 0x"+raw.mcError.toString(16).toUpperCase()+"] "+raw.mcErrorText;
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { processGroup(gi + 1); }, 0);
                    } else if (raw) {
                        grp.tags.forEach(function (t) {
                            var key = grp.regType + t.addr;
                            var rv = raw[key];
                            var q = 0;
                            if (rv === undefined || rv === null) { q = 2; rv = null; }
                            else if (!isBit) {
                                var dt = t.dataType || "INT16";
                                if (dt === "UINT16") { if (rv < 0) rv = rv + 65536; }
                                else if (dt === "INT32" || dt === "UINT32" || dt === "FLOAT32") {
                                    var adj = raw[grp.regType + (t.addr + 1)];
                                    if (adj === undefined || adj === null) { q = 2; rv = null; }
                                    else {
                                        var hi = rv, lo = adj;
                                        var combined = (hi << 16) | (lo & 0xFFFF);
                                        if (dt === "INT32") { rv = (combined > 0x7FFFFFFF) ? combined - 0x100000000 : combined; }
                                        else if (dt === "UINT32") { rv = combined >>> 0; }
                                        else if (dt === "FLOAT32") {
                                            var buf32 = Buffer.alloc(4);
                                            buf32.writeInt16LE(hi, 0); buf32.writeInt16LE(lo, 2);
                                            rv = parseFloat(buf32.readFloatLE(0).toFixed(4));
                                        }
                                    }
                                }
                            }
                            allStdData[t.id] = {
                                rawValue: rv,
                                quality: q,
                                ts: new Date().toISOString()
                            };
                        });
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { processGroup(gi + 1); }, 0);
                    } else {
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                    }
                }
            }
        } catch(_e) { node.warn('[MC-Driver] data handler error: '+_e.message); if(!resolved){resolved=true;try{client.destroy();}catch(e2){}} setTimeout(function(){processGroup(gi+1);},0); }  // 🔧 BUG-2
        });

        client.on('timeout', function () {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('error', function (e) {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e2) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('close', function () {
            if (!resolved) {
                resolved = true;
                if (buf.length === 0) {
                    hasFailed = true;
                    if (!firstError) firstError = '[NETWORK] TCP closed (no data) on '+grp.regType+startA;
                    setTimeout(function () { processGroup(gi + 1); }, 0);
                } else {
                    try { client.destroy(); } catch (e) {}
                    setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                }
            }
        });
    }

    attemptGroup(0);
}

try { processGroup(0); } catch(e) {
    node.warn("[MC-Driver] Uncaught exception: " + e.message);
    global.set("edge_mc_driver_lock", null);  // 🔧 BUG-2: Release lock on exception
}
return null;
